    }

    // Precompute a per-column scaling factor:
    //   inv_std[j] = 1 / (sqrt(float_n) * stddev[j])
    // so that normalization becomes a fused multiply instead of a divide.
    Func inv_std("inv_std");
    {
        Expr one = cast<num_t>(Expr(1.0));
        Expr sqrt_n = sqrt(float_n_param);
        inv_std(j) = one / (sqrt_n * stddev(j));
    }

    // Center and reduce the column vectors:
    // Original C:
    //   for (i = 0; i < N; i++)
    //     for (j = 0; j < M; j++) {
    //       data[i][j] -= mean[j];
    //       data[i][j] /= sqrt(float_n) * stddev[j];
    //     }
    //
    // We'll compute a new Func `normalized(j, i)` instead of modifying data in place:
    //   normalized(j, i) = (data[i][j] - mean[j]) * inv_std[j]
    Func normalized("normalized");
    {
        normalized(j, i) = (data_param(j, i) - mean(j)) * inv_std(j);
    }

    // Correlation matrix:
    // Original C:
    //   for (i = 0; i < M-1; i++) {
    //     corr[i][i] = 1.0;
    //     for (j = i+1; j < M; j++) {
    //       corr[i][j] = 0.0;
    //       for (k = 0; k < N; k++)
    //         corr[i][j] += data[k][i] * data[k][j];
    //       corr[j][i] = corr[i][j];
    //     }
    //   }
    //   corr[M-1][M-1] = 1.0;
    //
    // Using normalized data, the off-diagonals are dot products of
    // normalized columns. We compute the full symmetric matrix and then
    // explicitly set the diagonal to 1.0 to match the original semantics.
    Func corr_base("corr_base");
    {
        RDom r_k(0, n, "r_k");
        Expr zero = cast<num_t>(Expr(0.0));

        corr_base(q, p) = zero;
        corr_base(q, p) += normalized(q, r_k) * normalized(p, r_k);
    }

    Func corr("corr");
    {
        Expr one = cast<num_t>(Expr(1.0));
        // corr_buf(q, p) corresponds to C corr[p][q]
        corr(q, p) = select(p == q, one, corr_base(q, p));
    }

    // --------------------------------------------------------------------
    // Scheduling: improve locality and parallelism while preserving math
    // --------------------------------------------------------------------

    // Query the host target to pick reasonable vector widths.
    Target target = get_jit_target_from_environment();
    const int VEC_WIDTH = std::max(1, target.natural_vector_size(type_of<num_t>()));

    // Tunable tile sizes; adjust for different cache hierarchies if desired.
    const int COL_BLOCK = VEC_WIDTH * 4; // tile/block size along column-like dims (j, p, q)
    const int ROW_BLOCK = 64;           // tile/block size along row-like dims (i / sample dim)

    // Schedule for mean: reduction over rows, independent across columns.
    {
        Var jo("mean_jo"), ji("mean_ji");
        mean.compute_root();
        mean.update()
            .split(j, jo, ji, COL_BLOCK)
            .parallel(jo)
            .vectorize(ji, VEC_WIDTH);
    }

    // Schedule for var: similar pattern as mean.
    {
        Var jo("var_jo"), ji("var_ji");
        var.compute_root();
        var.update()
            .split(j, jo, ji, COL_BLOCK)
            .parallel(jo)
            .vectorize(ji, VEC_WIDTH);
    }

    // stddev is a pure 1D Func of j.
    {
        Var jo("std_jo"), ji("std_ji");
        stddev
            .compute_root()
            .split(j, jo, ji, COL_BLOCK)
            .parallel(jo)
            .vectorize(ji, VEC_WIDTH);
    }

    // inv_std is also 1D in j.
    {
        Var jo("inv_jo"), ji("inv_ji");
        inv_std
            .compute_root()
            .split(j, jo, ji, COL_BLOCK)
            .parallel(jo)
            .vectorize(ji, VEC_WIDTH);
    }

    // normalized is 2D over (j, i). We:
    //  * tile over (j, i) for better cache locality
    //  * parallelize across tiles of the slower-varying dimension (rows)
    //  * vectorize across j, which is stride-1 in memory.
    {
        Var jo("norm_jo"), ji("norm_ji");
        Var io("norm_io"), ii("norm_ii");
        normalized
            .compute_root()
            .tile(j, i, jo, io, ji, ii, COL_BLOCK, ROW_BLOCK)
            .parallel(io)
            .vectorize(ji, VEC_WIDTH);
    }

    // corr_base is a 2D reduction over (q, p) with reduction var r_k.
    // We:
    //  * compute it at root to avoid recomputing for corr()
    //  * parallelize across p (independent columns of the correlation matrix)
    //  * vectorize across q (contiguous dimension), so loads from normalized(q, r_k)
    //    become vector loads.
    {
        Var qo("corrb_qo"), qi("corrb_qi");
        corr_base.compute_root();

        // Schedule the reduction update step.
        corr_base.update()
            .split(q, qo, qi, COL_BLOCK)
            .parallel(p)
            .vectorize(qi, VEC_WIDTH);
    }

    // Final corr():
    // Just a pure mapping from corr_base plus diagonal fixup.
    {
        Var qo("corr_qo"), qi("corr_qi");
        corr
            .compute_root()
            .split(q, qo, qi, COL_BLOCK)
            .parallel(p)
            .vectorize(qi, VEC_WIDTH);
    }

    // Bind parameters and input buffer.
    data_param.set(data);
    float_n_param.set(float_n);

    // Build a pipeline for the final correlation Func.
    Pipeline pipeline(corr);

    // JIT compile the pipeline for the chosen target.
    pipeline.compile_jit(target);

    // Time only the kernel execution (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize corr into corr_buf.
    pipeline.realize(corr_buf);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result, similar to gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < m; jj++) {
                // corr_buf(jj, ii) corresponds to corr[ii][jj] in C.
                std::cerr << corr_buf(jj, ii) << '\n';
            }
        }
    }

    // Print timing (seconds).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
